:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #a0a0b0;
  --border: #0f3460;
}
* { box-sizing: border-box; margin: 0; padding: 0; }
body {
  min-height: 100vh;
  display: grid;
  place-items: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}
.card {
  width: min(100%, 480px);
  background: var(--card);
  border: 4px solid var(--border);
  border-radius: 0;
  padding: 24px;
  box-shadow: 8px 8px 0 rgba(0,0,0,0.4);
}
h1 {
  font-size: 1.5rem;
  margin-bottom: 16px;
  letter-spacing: 1px;
  text-transform: uppercase;
  color: var(--accent);
}
.input-row {
  display: flex;
  gap: 8px;
  margin-bottom: 16px;
}
input[type="text"] {
  flex: 1;
  padding: 12px;
  font-size: 1rem;
  background: var(--bg);
  border: 2px solid var(--border);
  color: var(--text);
  border-radius: 0;
  min-width: 0;
}
input[type="text"]:focus {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}
button {
  padding: 12px 20px;
  font-size: 1rem;
  font-weight: bold;
  background: var(--accent);
  color: #fff;
  border: 2px solid var(--accent);
  border-radius: 0;
  cursor: pointer;
  text-transform: uppercase;
  transition: background 0.1s, transform 0.1s;
}
button:hover { background: #c73650; }
button:focus-visible { outline: 3px solid #fff; outline-offset: 2px; }
button:active { transform: translate(2px, 2px); }
.counts {
  display: flex;
  justify-content: space-between;
  padding: 8px 0;
  border-bottom: 2px solid var(--border);
  margin-bottom: 12px;
  color: var(--muted);
  font-size: 0.95rem;
}
.counts span span { color: var(--text); font-weight: bold; }
.task-list { list-style: none; display: flex; flex-direction: column; gap: 8px; }
.task-list li {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px;
  background: var(--bg);
  border: 2px solid var(--border);
}
.task-list li span { flex: 1; word-break: break-word; }
.task-list li.done span { text-decoration: line-through; color: var(--muted); }
.task-list input[type="checkbox"] {
  width: 20px;
  height: 20px;
  accent-color: var(--accent);
  cursor: pointer;
  flex-shrink: 0;
}
.task-list input[type="checkbox"]:focus-visible { outline: 3px solid var(--accent); outline-offset: 2px; }
.delete-btn {
  padding: 6px 10px;
  font-size: 0.8rem;
  background: transparent;
  border: 2px solid var(--accent);
  color: var(--accent);
}
.delete-btn:hover { background: var(--accent); color: #fff; }
.sr-only {
  position: absolute; width: 1px; height: 1px;
  padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0,0,0,0); border: 0;
}
@media (max-width: 400px) {
  .card { padding: 16px; }
  .input-row { flex-direction: column; }
  button { width: 100%; }
}

const tasks = [];
let nextId = 1;

const input = document.getElementById('todo-input');
const addBtn = document.getElementById('todo-add');
const form = document.getElementById('todo-form');
const list = document.getElementById('todo-list');
const totalEl = document.getElementById('todo-total');
const remainingEl = document.getElementById('remaining');

function updateCounts() {
  totalEl.textContent = tasks.length;
  remainingEl.textContent = tasks.filter(t => !t.done).length;
}

function addTask() {
  const text = input.value.trim();
  if (!text) return;

  const id = nextId++;
  const task = { id, text, done: false };
  tasks.push(task);

  const li = document.createElement('li');
  li.id = `todo-item-${id}`;

  const checkbox = document.createElement('input');
  checkbox.type = 'checkbox';
  checkbox.id = `todo-check-${id}`;
  checkbox.setAttribute('aria-label', `Mark "${text}" as done`);
  checkbox.addEventListener('change', () => {
    task.done = checkbox.checked;
    li.classList.toggle('done', task.done);
    updateCounts();
  });

  const span = document.createElement('span');
  span.id = `todo-text-${id}`;
  span.textContent = text;

  const del = document.createElement('button');
  del.id = `todo-delete-${id}`;
  del.className = 'delete-btn';
  del.textContent = 'Delete';
  del.setAttribute('aria-label', `Delete "${text}"`);
  del.addEventListener('click', () => {
    const idx = tasks.indexOf(task);
    if (idx > -1) tasks.splice(idx, 1);
    li.remove();
    updateCounts();
  });

  li.append(checkbox, span, del);
  list.appendChild(li);
  input.value = '';
  input.focus();
  updateCounts();
}

form.addEventListener('submit', (e) => {
  e.preventDefault();
  addTask();
});

addBtn.addEventListener('click', addTask);

updateCounts();
